    ['no' => 30, 'level' => '中吉', 'title' => '丙癸 中吉', 'verse' => ['奉公谨守莫欺心', '自有亨通吉利临', '目下营求且休矣', '私期与子定佳音'], 'gist' => '奉公守己，佳音自至', 'interpretation' => '此签劝人奉公守己、静候佳音。事业：目下营求且止，守己则亨通；财运：勿妄取；姻缘：有期；健康：安泰。莫欺心、莫妄为，谨守正道，自有吉利临门，私下期许之事终有佳音。'],
    ['no' => 31, 'level' => '中吉', 'title' => '丁甲 中吉', 'verse' => ['秋冬作事只寻常', '春到门庭渐吉昌', '千里信音符远望', '萱堂快乐未渠央'], 'gist' => '渐入佳境，家道昌隆', 'interpretation' => '此签主渐入佳境、家道昌隆。事业：秋冬平常，春到渐吉，功名始彰；财运：财始达；姻缘：良配；健康：病渐康。行人渐近，信音在望。凡事向后愈佳，萱堂快乐、福禄日昌。'],
    ['no' => 32, 'level' => '下下', 'title' => '丁乙 下下', 'verse' => ['劳心泊泊竟何归', '疾病兼多是与非', '事到头来浑似梦', '何如休要用心机'], 'gist' => '劳而无功，不如息心', 'interpretation' => '此签主劳而无功、不如息心。事业：功名未通，用心机反受累；财运：财空；姻缘：未合；健康：病者险，多是非缠身。事到头来浑似梦，不如放下机心，安分守拙，免致心神俱疲。'],
    ['no' => 33, 'level' => '中吉', 'title' => '丁丙 中吉', 'verse' => ['不分南北与西东', '眼底昏昏耳似聋', '熟读黄庭经一卷', '不论贵贱与穷通'], 'gist' => '昏昧之时，修善避祸', 'interpretation' => '此签主昏昧之时、修善避祸。事业：名利俱滞，不宜妄想；财运：守成为要；姻缘：缓图；健康：静心调养。当此蒙昧之际，只宜谨守避祸、作福修善，自有神助，贵贱穷通不必论。'],
    ['no' => 34, 'level' => '中吉', 'title' => '丁丁 中吉', 'verse' => ['春夏才过秋又冬', '纷纷谋虑搅心胸', '贵人垂手来相援', '休把私心情意浓'], 'gist' => '贵人相援，莫徇私情', 'interpretation' => '此签主贵人相援、莫徇私情。事业：谋虑虽繁，有贵人垂手相助；财运：财禄有；姻缘：莫强求；健康：病渐愈。忌远谋、防口舌。心怀坦荡、不假私情，自然免却闷愁，诸事渐顺。'],
    ['no' => 35, 'level' => '下下', 'title' => '丁戊 下下', 'verse' => ['一山如画对清江', '门里团圆事事双', '谁料半途分析去', '空帏无语对银缸'], 'gist' => '团圆难保，谨防分离', 'interpretation' => '此签为团圆中变之兆。事业：事防中变，不可盲目乐观；财运：财有伤；姻缘：婚事不合，防中途分离；健康：病者险，家防重丧。眼前虽事事成双，谁料半途分析。凡事谨防行藏，守静为安。'],
    ['no' => 36, 'level' => '上吉', 'title' => '丁己 上吉', 'verse' => ['功名富贵自能为', '偶着仙鞭莫问伊', '万里鹏程君有分', '吴山顶上好钻龟'], 'gist' => '鹏程万里，戒在躁进', 'interpretation' => '此签主前程远大、戒在躁进。事业：功名富贵自能为，鹏程万里有分，但欲速则不达；财运：渐旺；姻缘：可成；健康：安泰。天机不可尽泄，稳扎稳打，自有登顶分晓之日。'],
    ['no' => 37, 'level' => '中吉', 'title' => '丁庚 中吉', 'verse' => ['焚香来告复何辞', '善恶平分汝自知', '屏却昧公心里事', '出门无碍是通时'], 'gist' => '改过向善，无碍亨通', 'interpretation' => '此签主改过向善、无碍亨通。事业：名有望，屏去私心则通；财运：财颇难，勿贪；姻缘：可合；健康：病祷安。善恶自分，天知自知。屏却昧心之事，出门无碍，正是亨通之时。'],
    ['no' => 38, 'level' => '下下', 'title' => '丁辛 下下', 'verse' => ['蛩吟唧唧守孤帏', '千里悬悬望信归', '等得荣华公子到', '秋冬括括雨霏霏'], 'gist' => '音信杳然，守静祷神', 'interpretation' => '此签主音信杳然、守静为宜。事业：谋事无成，勿妄动；财运：莫问；姻缘：未成；健康：病且重，宜祷神兼早医。孤帏独守、千里悬望，纵有所待亦如秋冬苦雨。凡事忍耐，静待转机。'],
    ['no' => 39, 'level' => '中平', 'title' => '丁壬 中下', 'verse' => ['北山门下好安居', '若问终时慎厥初', '堪笑包藏许多事', '鳞鸿虽便莫修书'], 'gist' => '守旧慎初，不可妄为', 'interpretation' => '此签主守旧慎初、不可妄为。事业：安居为上，不可轻动；财运：守；姻缘：审慎；健康：安。包藏之事虽多，须慎终如始。书信往来亦须谨慎，免生枝节。守得本份，方保安居。'],
    ['no' => 40, 'level' => '上吉', 'title' => '丁癸 上吉', 'verse' => ['新来换得好规模', '何用随他步与趋', '只听耳边消息到', '崎岖历尽见亨衢'], 'gist' => '历尽崎岖，终见坦途', 'interpretation' => '此签主先难后易、终见坦途。事业：改换新规模，不必随人步趋，崎岖历尽自见亨衢；财运：渐通；姻缘：后成；健康：安。只听耳边好消息到来，坚持自有出头之日。'],
    ['no' => 41, 'level' => '上吉', 'title' => '戊甲 上吉', 'verse' => ['自南自北自东西', '欲到天涯谁作梯', '遇鼠逢牛三弄笛', '好将姓名榜头题'], 'gist' => '先难后易，榜上有名', 'interpretation' => '此签主四方得志、先难后易。事业：东西南北皆可往，功名有待，遇子丑之期（鼠牛之年月）榜上有名；财运：渐至；姻缘：可成；健康：安。天涯有路，贵人作梯，凡事先难后易，终成大器。'],
    ['no' => 42, 'level' => '中吉', 'title' => '戊乙 中吉', 'verse' => ['我曾许汝事和谐', '谁料修为汝自乖', '但改新图莫依旧', '营谋应得称心怀'], 'gist' => '改过从新，营谋称心', 'interpretation' => '此签主改过从新、营谋称心。事业：旧法已乖，改弦更张则事谐；财运：改图后得；姻缘：重修旧好；健康：安。人非圣贤孰能无过，过而能改善莫大焉。但改新图莫依旧，营谋自然称怀。'],
    ['no' => 43, 'level' => '中吉', 'title' => '戊丙 中吉', 'verse' => ['一纸官书火急催', '扁舟速下浪如雷', '虽然目下多惊险', '保汝平安去复回'], 'gist' => '惊险过后，平安往返', 'interpretation' => '此签主惊险无虞、平安往返。事业：事虽火急惊险，终保平安；财运：有惊有得；姻缘：可成；健康：无虞。官书火急、浪急如雷，目下虽多惊险，神明保汝去复回。放心前行，化险为夷。'],
    ['no' => 44, 'level' => '中吉', 'title' => '戊丁 中吉', 'verse' => ['汝是人中最吉人', '误为误作损精神', '坚牢一念酬香愿', '富贵荣华萃汝身'], 'gist' => '坚心酬愿，福贵萃身', 'interpretation' => '此签主本是吉人、莫自误。事业：误为误作徒损精神，坚心酬愿则富贵萃身；财运：勿妄动；姻缘：莫急求；健康：病宜祷神，勿滥药。能自悔则利名双全，坚定善念，福报自来。'],
    ['no' => 45, 'level' => '中吉', 'title' => '戊戊 中吉', 'verse' => ['好将心地力耕耘', '彼此山头总是坟', '阴地不如心地好', '修为到底却输君'], 'gist' => '修心为上，福田自种', 'interpretation' => '此签主修心为上、福田自种。事业：心地好则百事顺，功名渐至；财运：财勿强求，守己为要；姻缘：可成；健康：病即安。阴地不如心地好，修为到底福自临。心存善念，天必佑之。'],
    ['no' => 46, 'level' => '中平', 'title' => '戊己 中平', 'verse' => ['君是山中万户侯', '信知骑马胜骑牛', '今朝马上看山色', '争似骑牛得自由'], 'gist' => '安守知足，勿贪外求', 'interpretation' => '此签主知足安闲、勿贪外求。事业：名利勿贪求，静处为佳；财运：守成；姻缘：莫轻许；健康：安。万户侯虽贵，不如骑牛得自由。骑马看山不如安步当车，谨守修为，清闲是福。'],
    ['no' => 47, 'level' => '中平', 'title' => '戊庚 中平', 'verse' => ['与君万语复千言', '祇欲平和雪尔冤', '讼则终凶君记取', '试于清夜把心扪'], 'gist' => '息讼平和，反躬自省', 'interpretation' => '此签主息讼和平、反躬自省。事业：循理则安，兴讼终凶；财运：财莫贪；姻缘：婚难成；健康：病未宁。千言万语只劝平和，清夜扪心自省。忍一时之气，保身家和平。'],
    ['no' => 48, 'level' => '中吉', 'title' => '戊辛 中吉', 'verse' => ['登山涉水正天寒', '兄弟姻亲那得安', '幸遇虎头人一唤', '全家遂保汝重欢'], 'gist' => '险中遇贵，转忧为喜', 'interpretation' => '此签主险中遇贵、转忧为喜。事业：目下天寒路险，遇贵人（虎头人，或属虎者、寅年月）一唤则全家重欢；财运：财物暂耗；姻缘：婚宜缓；健康：病虽惊险终愈。逢寅字事渐亨通。'],
    ['no' => 49, 'level' => '下下', 'title' => '戊壬 下下', 'verse' => ['彼此家居只一山', '如何似隔鬼门关', '日月如梭人易老', '许多劳碌不如闲'], 'gist' => '劳碌无成，不如安闲', 'interpretation' => '此签主劳碌无成、安闲为福。事业：名利阻隔，且休问；财运：勿求；姻缘：迟滞；健康：安养为宜。一山之隔如鬼门关，日月如梭人易老。与其奔波劳碌，不如安分守己，反得吉庆。'],
    ['no' => 50, 'level' => '上吉', 'title' => '戊癸 上吉', 'verse' => ['人说今年胜旧年', '也须步步要周旋', '一家和气多生福', '萋菲谗言莫听偏'], 'gist' => '家和生福，莫听谗言', 'interpretation' => '此签主家和生福、莫听谗言。事业：今年胜旧年，但须步步周旋，把握方针；财运：渐丰；姻缘：和美；健康：安。一家和气多生福，萋菲谗言切勿偏听。坚守正道，谋事可就。'],
    ['no' => 51, 'level' => '上吉', 'title' => '己甲 上吉', 'verse' => ['君今百事且随缘', '水到渠成听自然', '莫叹年来不如意', '喜逢新运称心田'], 'gist' => '随缘顺势，新运称心', 'interpretation' => '此签主随缘顺势、新运称心。事业：名渐显，水到渠成；财运：财自裕；姻缘：可定；健康：病自安。莫叹年来不如意，喜逢新运正当时。凡事听其自然，不必强求，命运渐亨心必称。'],
    ['no' => 52, 'level' => '上吉', 'title' => '己乙 上吉', 'verse' => ['兀坐幽居叹寂寥', '孤灯掩映度清宵', '万金忽报秋光好', '活计扁舟渡北朝'], 'gist' => '守得寂寥，晚景渐佳', 'interpretation' => '此签主守得寂寥、晚景渐佳。事业：名晚成、利迟得，秋光忽报好运来；财运：迟发而终厚；姻缘：吉；健康：病渐安。幽居清宵虽寂寞，终有万金之报。守得云开见月明，事胜往昔。'],
    ['no' => 53, 'level' => '下下', 'title' => '己丙 下下', 'verse' => ['艰难险阻路蹊跷', '南鸟孤飞依北巢', '今日贵人曾识面', '相逢却在夏秋交'], 'gist' => '险阻重重，待贵夏秋', 'interpretation' => '此签主险阻重重、贵人迟遇。事业：名财阻滞，贵人虽曾相识，迟至夏秋之交方逢；财运：滞；姻缘：缓；健康：病不利。南鸟依北巢，路途蹊跷难行。凡事忍耐，待时求助。'],
    ['no' => 54, 'level' => '中平', 'title' => '己丁 中平', 'verse' => ['万人丛里逞英豪', '便欲飞腾霄汉高', '争奈承流风未便', '青灯黄卷且勤劳'], 'gist' => '志高运滞，勤学待机', 'interpretation' => '此签主志高运滞、勤学待机。事业：欲飞腾而风未便，只可青灯黄卷勤奋努力，凡事以艰难得之；财运：迟；姻缘：缓；健康：安。时运未济仍须努力，厚积薄发，方有出头之日。'],
    ['no' => 55, 'level' => '中平', 'title' => '己戊 中平', 'verse' => ['勤耕力作莫蹉跎', '衣食随时安分过', '纵使经商收倍利', '不如逐岁廪禾多'], 'gist' => '勤耕安分，福自稳来', 'interpretation' => '此签主勤耕安分、福自稳来。事业：勤耕力作莫蹉跎，功名渐进；财运：经商纵有倍利，不如田禾岁岁安稳；姻缘：可就；健康：无灾。安分随时，戒贪戒躁，福自然来。'],
    ['no' => 56, 'level' => '下下', 'title' => '己己 下下', 'verse' => ['心头理曲强词遮', '直欲欺官行路斜', '一旦丑形临月镜', '身役宪网莫咨嗟'], 'gist' => '昧己欺人，终陷法网', 'interpretation' => '此签为欺心败露之戒。事业：理曲强词终难遮，功名无望；财运：勿贪不义之财；姻缘：不成；健康：有疾宜正视。瞒心昧己、欺公枉法之事，一旦丑形毕露，身陷法网悔之晚矣。速速悔改，方免灾祸。'],
    ['no' => 57, 'level' => '中平', 'title' => '己庚 中平', 'verse' => ['事端百出虑虽长', '莫听人言自主张', '一着仙机君记取', '纷纷闹里更思量'], 'gist' => '自主主张，勿听人言', 'interpretation' => '此签主自主主张、勿听人言。事业：事端虽多，自己拿定主意方成；财运：自主经营为宜；姻缘：自决；健康：安。纷纷扰攘之中更须冷静思量，谋断在己，勿为人言所摇。'],
    ['no' => 58, 'level' => '上吉', 'title' => '己辛 上吉', 'verse' => ['苏秦三寸足平生', '富贵功名在此行', '更好修为阴骘事', '前程万理自通亨'], 'gist' => '口才成事，积德通亨', 'interpretation' => '此签主口才成事、积德通亨。事业：如苏秦以三寸之舌取富贵，功名在此一行；财运：丰；姻缘：宜定；健康：病即安。更须多修阴德，前程万里自然通亨，家道日盛。'],
    ['no' => 59, 'level' => '中平', 'title' => '己壬 中平', 'verse' => ['门衰户冷苦伶仃', '自叹祈求不一灵', '幸有祖宗阴骘在', '香烟未断续螟蛉'], 'gist' => '门庭冷落，赖祖荫续', 'interpretation' => '此签主门庭冷落、赖祖荫续。事业：名难保、财难图，守成为要；财运：难得；姻缘：可合；健康：病无虞。幸有祖宗阴德在，香烟未断、子嗣可续。多行方便、谨持修持，渐转家运。'],
    ['no' => 60, 'level' => '上上', 'title' => '己癸 上上', 'verse' => ['羡君兄弟好名声', '只管谦伪莫自矜', '丹诏槐黄相逼近', '巍巍科甲两同登'], 'gist' => '谦逊积德，科甲连登', 'interpretation' => '此签主兄弟同登、百般如意。事业：功名科甲双双得，名声鹊起；财运：旺；姻缘：美；健康：安。惟须谦虚、莫自矜夸，丹诏槐黄相逼近，前程不可限量。谦受益，满招损。'],
    ['no' => 61, 'level' => '中吉', 'title' => '庚甲 中吉', 'verse' => ['啸聚山林凶恶俦', '善良无事苦煎忧', '主人大笑出门去', '不用干戈盗贼休'], 'gist' => '有惊无险，盗贼自消', 'interpretation' => '此签主有惊无险、盗贼自消。事业：虽有凶险终成平夷，不必大动干戈；财运：守；姻缘：缓；健康：安。啸聚之众不足惧，正气临之邪自退。坦然处之，化险为夷。'],
    ['no' => 62, 'level' => '中吉', 'title' => '庚乙 中吉', 'verse' => ['百千人面虎狼心', '赖汝干戈用力深', '得胜回时秋渐老', '虎头城里喜相寻'], 'gist' => '奋勇克敌，秋后得利', 'interpretation' => '此签主奋勇克敌、秋后得利。事业：须用力深，讼必胜、名可称；财运：财必进；姻缘：可成；健康：病有祟宜禳解。虎狼之辈虽多，奋力自持，得胜回时秋渐老，百事顺遂。'],
    ['no' => 63, 'level' => '中吉', 'title' => '庚丙 中吉', 'verse' => ['曩时败北且图南', '筋力虽衰尚一堪', '欲识生前君大数', '前三三与后三三'], 'gist' => '成败在天，尽力而为', 'interpretation' => '此签主败后图南、尽力听天。事业：昔日败北且图南进，筋力虽衰尚堪一搏，成败有数；财运：缓；姻缘：迟；健康：安。谋事在人成事在天，尽其在我，仍有成功之日。'],
    ['no' => 64, 'level' => '上上', 'title' => '庚丁 上上', 'verse' => ['吉人相遇本合同', '况有持谋天水翁', '人力不劳公论协', '事成功倍笑谈中'], 'gist' => '贵人合同，事半功倍', 'interpretation' => '此签主贵人合同、事半功倍。事业：吉人相遇、更有贵人（天水翁，赵姓或北方贵人）相助，事成功倍；财运：有余；姻缘：好；健康：病可疗。人力不劳而公论自协，笑谈中大事已成。'],
    ['no' => 65, 'level' => '上上', 'title' => '庚戊 上上', 'verse' => ['朔风凛凛正穷冬', '多羡门庭喜气浓', '更入新春人事后', '衷言方得信先容'], 'gist' => '否极泰来，新春转吉', 'interpretation' => '此签主否极泰来、新春转吉。事业：穷冬虽寒，门庭喜气渐浓，入春后人事皆顺；财运：渐丰；姻缘：可成；健康：安。朔风过后即是春风，化凶为吉。衷言得信，静候新春佳讯。'],
    ['no' => 66, 'level' => '上上', 'title' => '庚己 上上', 'verse' => ['耕耘只可在乡邦', '何用求谋向外方', '见说今年新运好', '门阑喜气事双双'], 'gist' => '安守本土，喜事成双', 'interpretation' => '此签主安守本土、喜事成双。事业：耕耘只宜在乡邦，外求无益，今年新运好、名高扬；财运：渐丰；姻缘：可结；健康：病即安。门阑喜气事双双，莫向外方求谋，守家得福。'],
    ['no' => 67, 'level' => '中平', 'title' => '庚庚 中平', 'verse' => ['谗发君心天已知', '何须问我决狐疑', '愿子改图从孝悌', '不愁家室不相宜'], 'gist' => '改过孝悌，家室自和', 'interpretation' => '此签主改过孝悌、家室自和。事业：改图从新则事成；财运：平；姻缘：和；健康：安。谗言疑心天已知，何须狐疑不决。愿子改过自新、力行孝悌，家室自然相宜，祸去福来。'],
    ['no' => 68, 'level' => '中吉', 'title' => '庚辛 中吉', 'verse' => ['南贩珍珠北贩盐', '年来几倍侦财添', '劝君止此求田舍', '心欲多时何日厌'], 'gist' => '见好即收，知足常乐', 'interpretation' => '此签主见好即收、知足常乐。事业：名利已成勿再贪求，求田舍安身为上；财运：财已添，莫再贪；姻缘：已定；健康：病自散。南贩北卖获利数倍，心欲多时何日厌。知足安分，方保长久。'],
    ['no' => 69, 'level' => '中平', 'title' => '庚壬 中平', 'verse' => ['舍舟遵路总相宜', '慎勿嬉游逐贵儿', '一夜樽前兄与弟', '明朝仇敌又相随'], 'gist' => '慎择交游，防人反目', 'interpretation' => '此签主慎择交游、防人反目。事业：名利莫强求，出入谨慎；财运：守；姻缘：难谋；健康：医宜审慎。舍舟遵路虽相宜，切勿嬉游依附贵儿。樽前兄弟、明朝仇敌，交游不慎祸将至。'],
    ['no' => 70, 'level' => '中吉', 'title' => '庚癸 中吉', 'verse' => ['雷雨风云各有司', '至诚祷告莫生疑', '与君约定为霖日', '正是蕴隆中伏时'], 'gist' => '至诚祷告，伏日应期', 'interpretation' => '此签主至诚感神、应期有日。事业：名利姑少待，约定之期（中伏之时）必应；财运：迟至；姻缘：婚宜迟；健康：病渐解。雷雨风云各有司，至诚祷告莫生疑，近期自有灵验。'],
    ['no' => 71, 'level' => '中吉', 'title' => '辛甲 中吉', 'verse' => ['喜鹊檐前报好音', '知君千里欲归心', '绣帏重结鸳鸯带', '叶落霜飞寒色侵'], 'gist' => '佳音初报，秋冬有成', 'interpretation' => '此签主佳音初报、秋冬有成。事业：名渐通，谋望在秋冬；财运：时未至；姻缘：婚再和；健康：病主凶，宜早治。喜鹊檐前报好音，千里归心。然霜飞叶落寒色侵，凡事待秋冬方妥。'],
    ['no' => 72, 'level' => '中平', 'title' => '辛乙 中平', 'verse' => ['河渠傍路有高低', '可叹长途日己西', '纵有荣华好时节', '直须猴犬换金鸡'], 'gist' => '长途日暮，待时而通', 'interpretation' => '此签主前途多阻、迟岁方通。事业：长途日暮，险阻多端，待申酉戌交替之年（猴犬换金鸡）方得荣华；财运：迟；姻缘：缓；健康：安。河渠高低路不平，且忍耐守时，佳期在后。'],
    ['no' => 73, 'level' => '下下', 'title' => '辛丙 下下', 'verse' => ['忆昔兰房分半钗', '而今忽把信息乖', '痴心指望成连理', '到底谁知事不谐'], 'gist' => '旧情已乖，戒勿轻信', 'interpretation' => '此签主旧情已乖、戒勿轻信。事业：事不谐，勿痴心指望；财运：守；姻缘：旧约难成，防背信；健康：安。忆昔分钗之约，今已音信全乖。到底事不谐，及早回头，免致伤神。'],
    ['no' => 74, 'level' => '上吉', 'title' => '辛丁 上吉', 'verse' => ['崔巍崔巍复崔巍', '履险如夷去复来', '身似菩提心似镜', '长安一道放春回'], 'gist' => '履险如夷，苦尽甘来', 'interpretation' => '此签主履险如夷、苦尽甘来。事业：名利迍而后亨，险中去复来终达长安；财运：迟得；姻缘：先难后成；健康：病险而平。身似菩提、心似明镜，万般险阻皆化坦途，一道春回福自生。'],
    ['no' => 75, 'level' => '中吉', 'title' => '辛戊 中吉', 'verse' => ['生前结得好姻缘', '一笑相逢情自亲', '相当人物无高下', '得意休论富与贫'], 'gist' => '良缘天定，不计贫富', 'interpretation' => '此签主良缘天定、不计贫富。事业：事无阻，遇主成事；财运：财物聚；姻缘：天定好姻缘，一笑情自亲，得意休论贫富；健康：病即愈。良朋聚、行人回，凡事顺遂，情义为重。'],
    ['no' => 76, 'level' => '中平', 'title' => '辛己 中平', 'verse' => ['三千法律八千文', '此事如何说与君', '善恶两途君自做', '一生祸福此中分'], 'gist' => '善恶自分，祸福自取', 'interpretation' => '此签主善恶自分、祸福自取。事业：揣己量力，勿恃势凌人；财运：当量入为出；姻缘：婚更审；健康：病宜早禳。三千法律八千文，善恶两途君自做。一生祸福此中分，诸恶莫作，众善奉行。'],
    ['no' => 77, 'level' => '中平', 'title' => '辛庚 中下', 'verse' => ['木有根亥水有源', '君当自此究其原', '莫随道路人闲话', '讼则终凶是至言'], 'gist' => '究其根源，讼则终凶', 'interpretation' => '此签主究其根源、讼则终凶。事业：凡事寻根问底，勿随人言浮动；财运：守；姻缘：缓；健康：安。木有根水有源，事有本末。莫听道路闲话，兴讼终凶。谨慎不躁，方保无虞。'],
    ['no' => 78, 'level' => '下下', 'title' => '辛辛 下下', 'verse' => ['家道丰腴自饱温', '也须肚里立乾坤', '财多害己君当省', '福有胚胎祸有门'], 'gist' => '财多害己，积善防祸', 'interpretation' => '此签主财多害己、积善防祸。事业：守成为上，勿贪多财；财运：财多反害己，当自省；姻缘：平；健康：防口舌是非致疾。家道虽丰，须肚里立定乾坤。福有胚胎祸有门，积善去恶，莫贪无厌。'],
    ['no' => 79, 'level' => '中平', 'title' => '辛壬 中平', 'verse' => ['干亥来龙仔细看', '坎居午向自当安', '若移丑艮阴阳逆', '门户凋零家道难'], 'gist' => '依理守正，妄动招损', 'interpretation' => '此签主依理守正、妄动招损。事业：名利依理求，婚讼莫妄谋；财运：平；姻缘：慎；健康：病择医方无忧。来龙去向既定，妄移方位则阴阳逆、家道难。安于本位，勿轻举妄动。'],
    ['no' => 80, 'level' => '中平', 'title' => '辛癸 中平', 'verse' => ['一朝无事忽朝官', '也是门衰坟未安', '改换阴阳移祸福', '劝君莫作等闲看'], 'gist' => '改图更张，移祸为福', 'interpretation' => '此签主改图更张、移祸为福。事业：名利宜改图，另辟蹊径；财运：变则通；姻缘：婚别配；健康：病更医。一朝事起皆因根基未安，改换阴阳可移祸福。凡事莫作等闲看，及时调整为上。'],
    ['no' => 81, 'level' => '中吉', 'title' => '壬甲 中吉', 'verse' => ['假君财物自当还', '谋赖欺心他自奸', '幸有高堂明月镜', '请来对照破机关'], 'gist' => '欺人自欺，修心向善', 'interpretation' => '此签主欺人自欺、修心向善。事业：谋事先难后易，欺诈终自败；财运：借人财物自当还；姻缘：可成；健康：安。幸有高堂明镜照破机关，欺人者自欺。修心向善，方免反惹其祸。'],
    ['no' => 82, 'level' => '上吉', 'title' => '壬乙 上吉', 'verse' => ['彼亦俦中一辈贤', '劝君特达与周旋', '此时宾主欢相会', '他日王侯却并肩'], 'gist' => '结交贤者，他日并肩', 'interpretation' => '此签主结交贤者、他日并肩。事业：与贤者周旋，他日王侯并肩，名遇荐举；财运：财必获；姻缘：成；健康：病有愿愈。此时宾主欢会，善结人缘。福禄因积善而发，前程远大。'],
    ['no' => 83, 'level' => '下下', 'title' => '壬丙 下下', 'verse' => ['随分堂前赴粥坛', '何须妄想苦忧煎', '主张门户诚难事', '百岁安闲得几年'], 'gist' => '随分安闲，莫作妄想', 'interpretation' => '此签主随分安闲、莫作妄想。事业：主张门户诚难，宜随分退守；财运：勿求；姻缘：缓；健康：安养。堂前赴粥亦随分，何须妄想苦忧煎。人生百岁，安闲能得几年，知足便是福。'],
    ['no' => 84, 'level' => '中平', 'title' => '壬丁 中平', 'verse' => ['个中事绪更纷然', '当局须知一着先', '长舌妇人休酷听', '力行礼义要心坚'], 'gist' => '纷然事绪，心坚行义', 'interpretation' => '此签主纷然事绪、心坚行义。事业：事绪纷然，当局须着先鞭，力行礼义；财运：财缓求；姻缘：婚更审；健康：安。长舌之言休酷听，心志坚定、不为谗言所动，方能立于不败之地。'],
    ['no' => 85, 'level' => '中平', 'title' => '壬戊 中平', 'verse' => ['一春风雨正潇潇', '千里行人去路遥', '移寡就多君得计', '如何归路转无聊'], 'gist' => '随分守己，远行宜归', 'interpretation' => '此签主随分守己、远行宜归。事业：莫贪外利，移寡就多终无聊；财运：勿贪；姻缘：不利；健康：防外灾。一春风雨行人路遥，不如归去。祷神自助、福自来，安分随时为上。'],
    ['no' => 86, 'level' => '上吉', 'title' => '壬己 上吉', 'verse' => ['一舟行货好招邀', '积少成多自富饶', '常把他人比自己', '管须日后胜今朝'], 'gist' => '积少成多，后胜今朝', 'interpretation' => '此签主积少成多、后胜今朝。事业：凡事渐进，积少成多自富饶；财运：招邀得力，日渐丰盈；姻缘：可成；健康：安。常把他人比自己，知足知不足。管须日后胜今朝，稳步向前。'],
    ['no' => 87, 'level' => '中平', 'title' => '壬庚 中平', 'verse' => ['阴里详看怪尔曹', '舟中敌国笑中刀', '藩篱剖破浑无事', '一种天生惜羽毛'], 'gist' => '笑里藏刀，谨守自保', 'interpretation' => '此签主笑里藏刀、谨守自保。事业：名利难求，防舟中敌国、笑里藏刀；财运：莫贪；姻缘：不利；健康：病有祟宜祷。藩篱剖破反无事，放开怀抱。爱惜羽毛、谨守本分，勿与小人计较。'],
    ['no' => 88, 'level' => '上吉', 'title' => '壬辛 上吉', 'verse' => ['从前作事总徒劳', '才见新春时渐遭', '百计营求都得意', '更须守己莫心高'], 'gist' => '新春转运，守己莫骄', 'interpretation' => '此签主新春转运、守己莫骄。事业：从前徒劳，新春渐遇时，百计营求皆得意；财运：利至；姻缘：合；健康：病安。然须守己、切莫心高。名利随缘，谋望在新年，稳守成果。'],
    ['no' => 89, 'level' => '中吉', 'title' => '壬壬 中吉', 'verse' => ['樽前无事且高歌', '时未来时奈若何', '白马渡江嘶日暮', '虎头城里看巍峨'], 'gist' => '时未至兮，缓图则宜', 'interpretation' => '此签主时运未至、缓图则宜。事业：名晚遇、财尚迟，时未来时且高歌；财运：迟；姻缘：和合缓成；健康：病徐愈。白马渡江、虎头城巍，佳景在后。缓则宜，静待天时。'],
    ['no' => 90, 'level' => '中平', 'title' => '壬癸 中平', 'verse' => ['崆峒城里事如麻', '无事如君有几家', '劝汝不须勤致祷', '徒劳生事苦咨嗟'], 'gist' => '知足安闲，贪求徒劳', 'interpretation' => '此签主知足安闲、贪求徒劳。事业：无事如君有几家，安常处顺即是福，妄求反生事；财运：求财无；姻缘：未成；健康：病无虑。不须勤致祷，且安居。贪求之念一起，反招口舌烦恼。'],
    ['no' => 91, 'level' => '中吉', 'title' => '癸甲 中吉', 'verse' => ['佛说淘沙始见金', '只缘君子不劳心', '荣华总得诗书效', '妙里工夫仔细寻'], 'gist' => '淘沙见金，勤苦有成', 'interpretation' => '此签主淘沙见金、勤苦有成。事业：凡有谋望皆得成就，但须涉历勤苦，荣华总得诗书之力；财运：迟得；姻缘：可成；健康：安。佛说淘沙始见金，工夫到处方得宝。妙里工夫仔细寻。'],
    ['no' => 92, 'level' => '中平', 'title' => '癸乙 中下', 'verse' => ['今年禾谷不如前', '物价喧腾倍百年', '灾数流行多疫疠', '一阳复后始安全'], 'gist' => '灾疫流行，冬至始安', 'interpretation' => '此签主时运欠佳、一阳来复。事业：今年不如前，财禄难，时且待，冬至后（一阳复）始安全；财运：难；姻缘：缓；健康：病患多终无害，防时疫。灾数流行，忍耐过冬，禄终在。'],
    ['no' => 93, 'level' => '中吉', 'title' => '癸丙 中吉', 'verse' => ['春来雨水太连绵', '入夏晴干雨又愆', '节气直交三伏始', '喜逢滂沛足田园'], 'gist' => '先涝后旱，伏日方足', 'interpretation' => '此签主先涝后旱、伏日方足。事业：事多反复，直待三伏之期方得滂沛之喜；财运：财聚散无常；姻缘：婚可成，慎往复；健康：病反复。宜作福修善，进退有度，时至自安。'],
    ['no' => 94, 'level' => '中吉', 'title' => '癸丁 中吉', 'verse' => ['一般器用与人同', '巧斫轮舆梓匠工', '凡事有缘且随分', '秋冬方至主人翁'], 'gist' => '随分待时，秋冬遇贵', 'interpretation' => '此签主随分待时、秋冬遇贵。事业：凡事有缘且随分，名尚迟，秋冬方遇贵人；财运：缓；姻缘：婚未成，待时；健康：病未愈。巧匠斫轮自有其时，器用虽同遇合各异。秋冬方是有遇之期。'],
    ['no' => 95, 'level' => '中吉', 'title' => '癸戊 中吉', 'verse' => ['知君袖内有骊珠', '生不逢辰亦强图', '可叹头颅已如许', '而今方得贵人扶'], 'gist' => '怀才晚成，贵人终扶', 'interpretation' => '此签主怀才晚成、贵人终扶。事业：身怀骊珠而生不逢辰，强图无益，晚岁方得贵人扶持，名利晚成；财运：财发迟；姻缘：婚未决；健康：安。藏器待时，遇贵灾难灭，晚景自有发越。'],
    ['no' => 96, 'level' => '上吉', 'title' => '癸己 上吉', 'verse' => ['婚姻子息莫嫌迟', '但把精神把佛持', '四十年前须报应', '功圆行满有馨儿'], 'gist' => '迟来方实，中年得子', 'interpretation' => '此签主迟来方实、中年得子。事业：名利迟方吉；财运：缓至；姻缘：婚姻子息莫嫌迟，终成实；健康：病渐瘥。但把精神奉佛持，四十年前须报应，功圆行满自有佳儿。迟得反牢。'],
    ['no' => 97, 'level' => '上上', 'title' => '癸庚 上上', 'verse' => ['五十功名心已灰', '那知富贵逼人来', '更行好事存方寸', '寿比冈陵位鼎台'], 'gist' => '晚运大发，福寿双全', 'interpretation' => '此签主晚运大发、福寿双全。事业：五十功名心灰之际，富贵逼人而来，名可成；财运：财渐聚；姻缘：平顺；健康：病且宁，寿比冈陵。更行好事存方寸，位登鼎台，晚景荣昌。'],
    ['no' => 98, 'level' => '中吉', 'title' => '癸辛 中吉', 'verse' => ['经营百出费精神', '南北奔驰运未新', '玉兔交时当得意', '恰如枯木再逢春'], 'gist' => '奔驰未遇，卯岁逢春', 'interpretation' => '此签主奔驰未遇、卯岁逢春。事业：经营百出费精神，南北奔驰运未新，待卯年月（玉兔交时）方得意；财运：名利晚成；姻缘：缓；健康：病久方平。恰如枯木再逢春，守待卯运事皆亨。'],
    ['no' => 99, 'level' => '上上', 'title' => '癸壬 上上', 'verse' => ['贵人遭遇水云卿', '冷淡交情滋味长', '黄阁开时延故客', '骅溜应得骤康庄'], 'gist' => '贵人提拔，平步青云', 'interpretation' => '此签主贵人提拔、平步青云。事业：早遇贵人（水云卿）提携，他日黄阁大开、骅骝驰骋康庄，功名显赫；财运：丰；姻缘：成；健康：安。冷淡交情滋味长，君子之交终成大用。'],
    ['no' => 100, 'level' => '上上', 'title' => '癸癸 上上', 'verse' => ['我本天仙雷雨师', '吉凶祸福我先知', '至诚祷祝皆灵应', '抽得终签百事宜'], 'gist' => '至诚感通，百事如意', 'interpretation' => '此签为百签之终，主至诚感通、百事如意。事业：求谋无不遂意，前进后达；财运：遂；姻缘：成；健康：安。雷雨师自示灵感，至诚祷告皆有灵应。抽得此签百事宜，仍须以诚敬为本，行善积德。'],
